            { label: 'Apply for a premium rewards credit card', consequence: 'With no credit history, you\'ll be denied, and the hard inquiry slightly hurts your future applications. Premium cards require established credit.', score: 0 },
            { label: 'Ask a parent to add you as an authorized user on their oldest card', consequence: 'This is a good strategy, but it works best IN ADDITION to your own card. Being an authorized user alone doesn\'t establish your own credit account.', score: 2 }
